// Try YouTube's own captions via timedtext (free, no quota). Most videos
// have at least auto-generated EN captions. If empty, the next branch falls
// back to ytdl-core + OpenAI Whisper.
const body = $input.first().json.body ?? $input.first().json;
const videoId = body.video_id;
const url = body.url ?? `https://youtube.com/watch?v=${videoId}`;
if (!videoId) throw new Error('missing_video_id');
return [{ json: { video_id: videoId, url } }];

// Try to parse the timedtext JSON. If empty or malformed, signal a fallback.
const resp = $input.first().json;
let events = [];
if (typeof resp === 'object' && Array.isArray(resp.events)) {
  events = resp.events;
}
if (events.length === 0) {
  return [{ json: { needs_whisper: true, video_id: $('parse').first().json.video_id, url: $('parse').first().json.url } }];
}
const segments = events
  .filter((e) => Array.isArray(e.segs))
  .map((e) => ({
    start: (e.tStartMs ?? 0) / 1000,
    duration: (e.dDurationMs ?? 0) / 1000,
    text: e.segs.map((s) => s.utf8).join('').trim(),
  }))
  .filter((s) => s.text);
const text = segments.map((s) => s.text).join(' ').replace(/\s+/g, ' ').trim();
return [{
  json: {
    transcript_text: text,
    transcript_segments: segments,
    transcript_source: 'youtube-captions',
    cost_usd: 0,
  },
}];

// Shape the Whisper response into the same envelope as the captions path.
const resp = $input.first().json;
const segments = (resp.segments ?? []).map((s) => ({
  start: s.start,
  duration: s.end - s.start,
  text: s.text,
}));
return [{
  json: {
    transcript_text: resp.text ?? '',
    transcript_segments: segments,
    transcript_source: 'whisper',
    cost_usd: ((resp.duration ?? 0) / 60) * 0.006,
  },
}];
